script:
(function () {
  'use strict';
  // Simplified Social Security retirement estimate in today's dollars.
  //   AIME = min(earnings, wage base) x min(years, 35) / 35 / 12   (rounded down to the dollar)
  //   PIA  = 90% of AIME up to bend point 1 + 32% up to bend point 2 + 15% above (rounded down to the dime)
  //   Claiming before full retirement age (FRA): -5/9% per month for the first 36 months,
  //   -5/12% per month beyond. After FRA: +2/3% per month (8% a year) up to age 70.
  //   Monthly benefit is rounded down to the dollar, as SSA does.
  // Verified (Node, scratch tests): AIME $5,000 -> PIA $2,345.80 (1,157.40 + 1,188.48 rounded down
  //   to the dime); born 1970 (FRA 67) claiming at 62 = 70% -> $1,642; at 70 = 124% -> $2,908.
  //   FRA for 1957 = 66 and 6 months; claiming at 62 = 60 months early -> 72.5% of PIA.
  //   Fewer than 10 years of work -> not insured (no retirement benefit).
  //   $184,500 earnings for 35 years -> formula PIA $4,369.30, capped at SSA's 2026 FRA maximum $4,152;
  //   claiming at 70 (FRA 67) -> 124% -> $5,148.
  //
  // ---- 2026 SOCIAL SECURITY CONSTANTS (benefit year 2026) --------------------------------
  // Source: SSA, 2026 Social Security changes fact sheet and PIA formula bend points
  //   (ssa.gov/oact/cola/bendpoints.html); FRA schedule: 42 U.S.C. 416(l);
  //   early/delayed adjustments: 20 CFR 404.410 and 404.313.
  var BENEFIT_YEAR = 2026;
  var BEND_1 = 1286, BEND_2 = 7749;        // PIA formula bend points for workers first eligible in 2026
  var WAGE_BASE = 184500;                  // maximum earnings subject to Social Security tax in 2026
  var MIN_YEARS = 10;                      // 40 credits, roughly 10 years of covered work
  var MAX_FRA_BENEFIT = 4152;              // SSA: maximum monthly benefit at full retirement age in 2026
                                           //   (ssa.gov/faqs/en/questions/KA-01897.html)
  // ---------------------------------------------------------------------------------------

  var whole = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', maximumFractionDigits: 1 });

  function num(id) {
    var el = document.getElementById(id);
    if (!el) return NaN;
    var v = parseFloat(el.value);
    return isNaN(v) ? NaN : v;
  }

  function fraMonths(birthYear) {
    if (birthYear <= 1954) return 66 * 12;
    if (birthYear >= 1960) return 67 * 12;
    return 66 * 12 + (birthYear - 1954) * 2;
  }

  function ageLabel(months) {
    var y = Math.floor(months / 12), m = months % 12;
    return y + (m ? ' and ' + m + (m === 1 ? ' month' : ' months') : '');
  }

  function pia(earnings, years) {
    var aime = Math.floor(Math.min(earnings, WAGE_BASE) * Math.min(years, 35) / 35 / 12);
    var p = 0.9 * Math.min(aime, BEND_1) + 0.32 * Math.max(0, Math.min(aime, BEND_2) - BEND_1) +
            0.15 * Math.max(0, aime - BEND_2);
    return { aime: aime, pia: Math.floor(p * 10 + 1e-9) / 10 };
  }

  function factor(claimMonths, fra) {
    var diff = claimMonths - fra;
    if (diff < 0) {
      var early = -diff;
      return 1 - (Math.min(early, 36) * 5 / 900) - (Math.max(0, early - 36) * 5 / 1200);
    }
    return 1 + Math.min(diff, 70 * 12 - fra) * 2 / 300;
  }

  function setText(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }

  function update() {
    var birth = Math.round(num('ssBirth')), earnings = num('ssEarnings'), years = Math.round(num('ssYears')),
        claimY = Math.round(num('ssClaimAge')), claimM = Math.round(num('ssClaimMonths')), life = num('ssLife');
    var error = document.getElementById('ssError');
    var bad = [birth, earnings, years, claimY, claimM, life].some(function (v) { return !isFinite(v); }) ||
              birth < 1943 || birth > 2010 || earnings < 0 || years < 0 || years > 50 ||
              claimY < 62 || claimY > 70 || claimM < 0 || claimM > 11 || (claimY === 70 && claimM > 0) ||
              life < 62 || life > 110;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a birth year from 1943 to 2010, earnings of 0 or more, 0 to 50 work years, ' +
                          'a claiming age from 62 to 70 and a life expectancy from 62 to 110.';
      return;
    }
    var fra = fraMonths(birth), claim = claimY * 12 + claimM;
    var insured = years >= MIN_YEARS;
    var p = pia(earnings, years);
    // Level earnings at today's wage base overstate top benefits (past wage bases were lower in
    // real terms), so the full-retirement-age amount is capped at SSA's actual 2026 maximum.
    var capped = insured && p.pia > MAX_FRA_BENEFIT;
    var base = insured ? Math.min(p.pia, MAX_FRA_BENEFIT) : 0;
    var f = factor(claim, fra);
    var monthly = Math.floor(base * f + 1e-9);
    var lifetime = function (m, ageMonths) { return m * Math.max(0, Math.round(life * 12) - ageMonths); };

    setText('ssMonthly', whole.format(monthly));
    setText('ssAnnual', whole.format(monthly * 12));
    setText('ssLifetime', whole.format(lifetime(monthly, claim)));
    setText('ssFra', ageLabel(fra));
    setText('ssPia', whole.format(Math.floor(base)));
    setText('ssFactor', pct.format(f));
    setText('ssAime', whole.format(p.aime));

    var best = -1, bestAge = 0, rows = [];
    for (var age = 62; age <= 70; age++) {
      var fa = factor(age * 12, fra), m = Math.floor(base * fa + 1e-9), total = lifetime(m, age * 12);
      if (total > best + 0.5) { best = total; bestAge = age; }
      rows.push({ age: age, f: fa, m: m, total: total });
    }
    document.getElementById('ssTable').innerHTML = rows.map(function (r) {
      var mark = insured && best > 0 && r.age === bestAge ? ' <strong>(highest)</strong>' : '';
      return '<tr><td>' + r.age + '</td><td>' + pct.format(r.f) + '</td><td>' + whole.format(r.m) + '</td><td>' +
             whole.format(r.m * 12) + '</td><td>' + whole.format(r.total) + mark + '</td></tr>';
    }).join('');

    var notes = [];
    if (!insured) notes.push('You generally need 40 work credits (about ' + MIN_YEARS + ' years of covered work) to qualify for a retirement benefit, so this estimate shows $0.');
    if (birth + claimY < BENEFIT_YEAR) notes.push('That claiming age is in the past for your birth year. The figure shows what the formula gives, not what you are receiving.');
    if (capped) notes.push('The formula gives more than ' + whole.format(MAX_FRA_BENEFIT) + ' a month at full retirement age, which is the most SSA paid anyone reaching full retirement age in ' + BENEFIT_YEAR + ', so the estimate is capped there before the claiming-age adjustment.');
    if (earnings > WAGE_BASE) notes.push('Earnings above the ' + BENEFIT_YEAR + ' wage base of ' + whole.format(WAGE_BASE) + ' do not count toward benefits, so only that amount is used.');
    if (life * 12 <= claim) notes.push('Your life expectancy is at or below the claiming age, so the lifetime total is $0.');
    var noteEl = document.getElementById('ssNote');
    noteEl.hidden = notes.length === 0;
    noteEl.textContent = notes.join(' ');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('ssForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
